use std::{
    ffi::c_void,
    ffi::CStr,
    thread,
    time::{Duration, Instant},
};

use cocoa::{
    appkit::{NSPasteboard, NSPasteboardItem},
    base::{id, nil, NO},
    foundation::{NSArray, NSAutoreleasePool, NSData, NSString},
};
use objc::{
    runtime::{objc_autorelease, Class, Sel},
    Message,
};

use crate::GetTextError;

const COPY_KEYSTROKE_SCRIPT: &str =
    r#"tell application "System Events" to keystroke "c" using {command down}"#;
const TRANSIENT_MARKER_TYPES: [&str; 3] = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
];

/// 使用原生 NSPasteboard 事务执行 macOS 剪贴板 fallback。
pub(crate) fn copy_selected_text_with_native_transaction(
    max_wait_ms: u64,
) -> Result<String, GetTextError> {
    unsafe {
        let pool = NSAutoreleasePool::new(nil);
        let result = copy_selected_text_inside_pool(max_wait_ms);
        pool.drain();
        result
    }
}

unsafe fn copy_selected_text_inside_pool(max_wait_ms: u64) -> Result<String, GetTextError> {
    let pasteboard = NSPasteboard::generalPasteboard(nil);
    let mut transaction = NativePasteboardTransaction::begin(pasteboard)?;
    let sequence_before = transaction.prepare_for_copy()?;

    run_copy_keystroke()?;

    if !wait_for_change(pasteboard, sequence_before, max_wait_ms) {
        transaction.restore()?;
        return Ok(String::new());
    }

    // 复制后的 transient marker 只是降低剪贴板管理器记录风险，失败不应阻断读取。
    add_transient_markers_best_effort(pasteboard);
    let text = super::macos_pasteboard_text::read_pasteboard_text_best_effort(pasteboard)
        .unwrap_or_default();
    transaction.restore()?;

    Ok(text)
}

struct NativePasteboardTransaction {
    pasteboard: id,
    snapshot: PasteboardSnapshot,
    restored: bool,
}

impl NativePasteboardTransaction {
    /// 捕获当前 pasteboard 状态，后续 Drop 会兜底恢复。
    unsafe fn begin(pasteboard: id) -> Result<Self, GetTextError> {
        let snapshot = PasteboardSnapshot::capture(pasteboard);
        Ok(Self {
            pasteboard,
            snapshot,
            restored: false,
        })
    }

    /// 清空 pasteboard 并写入 transient marker，为模拟复制建立可检测基线。
    unsafe fn prepare_for_copy(&mut self) -> Result<i64, GetTextError> {
        self.pasteboard.clearContents();
        // 复制前 marker 用来建立可检测基线；若系统/应用暂时拒绝写入，仍继续尝试 Cmd+C。
        add_transient_markers_best_effort(self.pasteboard);
        Ok(self.pasteboard.changeCount())
    }

    /// 显式恢复原始 pasteboard 内容；重复调用保持幂等。
    unsafe fn restore(&mut self) -> Result<(), GetTextError> {
        if !self.restored {
            self.snapshot.restore(self.pasteboard)?;
            self.restored = true;
        }
        Ok(())
    }
}

impl Drop for NativePasteboardTransaction {
    fn drop(&mut self) {
        if !self.restored {
            unsafe {
                let _ = self.snapshot.restore(self.pasteboard);
            }
        }
    }
}

/// macOS pasteboard 快照，优先保留多 item 结构，必要时退回老式扁平类型快照。
struct PasteboardSnapshot {
    items: Vec<PasteboardItemSnapshot>,
    legacy_entries: Vec<PasteboardEntry>,
}

/// 单个 pasteboard 类型对应的原始 NSData 内容。
struct PasteboardEntry {
    type_name: String,
    data: Vec<u8>,
}

/// 单个 NSPasteboardItem 的所有可读取类型数据。
struct PasteboardItemSnapshot {
    entries: Vec<PasteboardEntry>,
}

impl PasteboardSnapshot {
    /// 捕获 pasteboard 当前内容，保持 item 边界以避免富文本/多对象剪贴板被拍平成单项。
    unsafe fn capture(pasteboard: id) -> Self {
        let items = capture_pasteboard_items(pasteboard);
        if !items.is_empty() {
            return Self {
                items,
                legacy_entries: Vec::new(),
            };
        }

        let legacy_entries = capture_pasteboard_types(pasteboard);
        Self {
            items: Vec::new(),
            legacy_entries,
        }
    }

    /// 按捕获时的结构恢复 pasteboard 内容。
    unsafe fn restore(&self, pasteboard: id) -> Result<(), GetTextError> {
        pasteboard.clearContents();

        if !self.items.is_empty() {
            return self.restore_items(pasteboard);
        }

        self.restore_legacy_entries(pasteboard)
    }

    /// 恢复多 item 快照。
    unsafe fn restore_items(&self, pasteboard: id) -> Result<(), GetTextError> {
        let restored_items = self
            .items
            .iter()
            .map(|snapshot| snapshot.to_nspasteboard_item())
            .collect::<Result<Vec<_>, _>>()?;
        let item_array = NSArray::arrayWithObjects(nil, &restored_items);
        if pasteboard.writeObjects(item_array) == NO {
            return Err(GetTextError::fallback_failed(
                "restore macOS pasteboard items failed",
            ));
        }

        Ok(())
    }

    /// 恢复旧式扁平类型快照，作为 `pasteboardItems` 不可用时的兼容路径。
    unsafe fn restore_legacy_entries(&self, pasteboard: id) -> Result<(), GetTextError> {
        for entry in &self.legacy_entries {
            let type_id = NSString::alloc(nil).init_str(&entry.type_name);
            let data = nsdata_from_bytes(&entry.data);
            if NSPasteboard::setData_forType(pasteboard, data, type_id) == NO {
                return Err(GetTextError::fallback_failed(format!(
                    "restore macOS pasteboard type {} failed",
                    entry.type_name
                )));
            }
        }

        Ok(())
    }
}

impl PasteboardItemSnapshot {
    /// 捕获单个 NSPasteboardItem 的所有可立即读取类型数据。
    unsafe fn capture(item: id) -> Option<Self> {
        let types = NSPasteboardItem::types(item);
        if types == nil {
            return None;
        }

        let mut entries = Vec::new();
        for index in 0..types.count() {
            let type_id = types.objectAtIndex(index);
            let Some(type_name) = nsstring_to_string(type_id) else {
                continue;
            };
            let data = NSPasteboardItem::dataForType(item, type_id);
            if data == nil {
                continue;
            }
            let bytes = nsdata_to_vec(data);
            entries.push(PasteboardEntry {
                type_name,
                data: bytes,
            });
        }

        if entries.is_empty() {
            None
        } else {
            Some(Self { entries })
        }
    }

    /// 将快照重建为新的 autoreleased NSPasteboardItem。
    unsafe fn to_nspasteboard_item(&self) -> Result<id, GetTextError> {
        let item = new_nspasteboard_item()?;
        for entry in &self.entries {
            let type_id = NSString::alloc(nil).init_str(&entry.type_name);
            let data = nsdata_from_bytes(&entry.data);
            if NSPasteboardItem::setData_forType(item, data, type_id) == NO {
                return Err(GetTextError::fallback_failed(format!(
                    "restore macOS pasteboard item type {} failed",
                    entry.type_name
                )));
            }
        }

        Ok(item)
    }
}

unsafe fn add_transient_markers_best_effort(pasteboard: id) -> bool {
    let marker_type_ids = TRANSIENT_MARKER_TYPES
        .iter()
        .map(|marker| NSString::alloc(nil).init_str(marker))
        .collect::<Vec<_>>();
    let marker_types = NSArray::arrayWithObjects(nil, &marker_type_ids);
    pasteboard.addTypes_owner(marker_types, nil);

    let empty_data = NSData::data(nil);
    let mut all_written = true;
    for marker_type in marker_type_ids {
        if NSPasteboard::setData_forType(pasteboard, empty_data, marker_type) == NO {
            all_written = false;
        }
    }

    all_written
}

/// 捕获 pasteboardItems，保留多 item 边界。
unsafe fn capture_pasteboard_items(pasteboard: id) -> Vec<PasteboardItemSnapshot> {
    let pasteboard_items = pasteboard.pasteboardItems();
    if pasteboard_items == nil {
        return Vec::new();
    }

    let mut snapshots = Vec::new();
    for index in 0..pasteboard_items.count() {
        let item = pasteboard_items.objectAtIndex(index);
        if let Some(snapshot) = PasteboardItemSnapshot::capture(item) {
            snapshots.push(snapshot);
        }
    }

    snapshots
}

/// 捕获老式 pasteboard 顶层类型，作为多 item API 不返回内容时的 fallback。
unsafe fn capture_pasteboard_types(pasteboard: id) -> Vec<PasteboardEntry> {
    let types = NSPasteboard::types(pasteboard);
    if types == nil {
        return Vec::new();
    }

    let mut entries = Vec::new();
    for index in 0..types.count() {
        let type_id = types.objectAtIndex(index);
        let Some(type_name) = nsstring_to_string(type_id) else {
            continue;
        };
        let data = NSPasteboard::dataForType(pasteboard, type_id);
        if data == nil {
            continue;
        }
        let bytes = nsdata_to_vec(data);
        entries.push(PasteboardEntry {
            type_name,
            data: bytes,
        });
    }

    entries
}

/// 创建新的 autoreleased NSPasteboardItem，并把 Objective-C runtime 错误映射为 fallback 错误。
unsafe fn new_nspasteboard_item() -> Result<id, GetTextError> {
    let item_class = Class::get("NSPasteboardItem")
        .ok_or_else(|| GetTextError::fallback_failed("NSPasteboardItem class is unavailable"))?;
    let item: id = item_class
        .send_message(Sel::register("alloc"), ())
        .map_err(|error| {
            GetTextError::fallback_failed(format!("alloc NSPasteboardItem: {error}"))
        })?;
    if item == nil {
        return Err(GetTextError::fallback_failed(
            "alloc NSPasteboardItem returned nil",
        ));
    }
    let item: id = (&*item)
        .send_message(Sel::register("init"), ())
        .map_err(|error| {
            GetTextError::fallback_failed(format!("init NSPasteboardItem: {error}"))
        })?;
    if item == nil {
        return Err(GetTextError::fallback_failed(
            "init NSPasteboardItem returned nil",
        ));
    }
    objc_autorelease(item);
    Ok(item)
}

unsafe fn nsstring_to_string(value: id) -> Option<String> {
    if value == nil {
        return None;
    }
    let c_string = value.UTF8String();
    if c_string.is_null() {
        return None;
    }
    CStr::from_ptr(c_string)
        .to_str()
        .ok()
        .map(ToOwned::to_owned)
}

unsafe fn nsdata_to_vec(data: id) -> Vec<u8> {
    let len = data.length() as usize;
    if len == 0 {
        return Vec::new();
    }
    let ptr = data.bytes().cast::<u8>();
    if ptr.is_null() {
        return Vec::new();
    }
    std::slice::from_raw_parts(ptr, len).to_vec()
}

unsafe fn nsdata_from_bytes(bytes: &[u8]) -> id {
    if bytes.is_empty() {
        NSData::data(nil)
    } else {
        NSData::dataWithBytes_length_(nil, bytes.as_ptr().cast::<c_void>(), bytes.len() as u64)
    }
}

fn wait_for_change(pasteboard: id, sequence_before: i64, max_wait_ms: u64) -> bool {
    let deadline = Instant::now() + Duration::from_millis(max_wait_ms.max(1));

    loop {
        let current = unsafe { pasteboard.changeCount() };
        if current != sequence_before {
            return true;
        }

        if Instant::now() >= deadline {
            return false;
        }

        thread::sleep(Duration::from_millis(8));
    }
}

fn run_copy_keystroke() -> Result<(), GetTextError> {
    let output = std::process::Command::new("osascript")
        .arg("-e")
        .arg(COPY_KEYSTROKE_SCRIPT)
        .output()
        .map_err(|error| GetTextError::fallback_failed(format!("run osascript: {error}")))?;

    if output.status.success() {
        Ok(())
    } else {
        Err(map_osascript_error(output.stderr))
    }
}

fn map_osascript_error(stderr: Vec<u8>) -> GetTextError {
    let message = String::from_utf8_lossy(&stderr).to_string();
    if message.contains("not allowed to send keystrokes") || message.contains("assistive access") {
        GetTextError::PermissionDenied {
            platform: "macOS",
            permission: "Accessibility",
            guidance: "Allow this application and System Events to control your computer in System Settings > Privacy & Security > Accessibility.",
        }
    } else {
        GetTextError::fallback_failed(message)
    }
}

#[cfg(test)]
mod tests {
    use super::{
        map_osascript_error, new_nspasteboard_item, nsdata_from_bytes, nsdata_to_vec,
        PasteboardSnapshot, COPY_KEYSTROKE_SCRIPT, TRANSIENT_MARKER_TYPES,
    };
    use crate::GetTextError;
    use cocoa::{
        appkit::{NSPasteboard, NSPasteboardItem},
        base::{id, nil, NO},
        foundation::{NSArray, NSAutoreleasePool, NSString},
    };

    const TEST_TYPE_ONE: &str = "com.get-selected-text.test.item-one";
    const TEST_TYPE_TWO: &str = "com.get-selected-text.test.item-two";

    #[test]
    fn copy_keystroke_script_only_sends_command_c() {
        assert!(COPY_KEYSTROKE_SCRIPT.contains("keystroke \"c\""));
        assert!(!COPY_KEYSTROKE_SCRIPT.contains("the clipboard"));
        assert!(!COPY_KEYSTROKE_SCRIPT.contains("set volume alert volume"));
    }

    #[test]
    fn transient_marker_types_match_macos_clipboard_manager_contract() {
        assert_eq!(TRANSIENT_MARKER_TYPES[0], "org.nspasteboard.TransientType");
        assert_eq!(TRANSIENT_MARKER_TYPES[1], "org.nspasteboard.ConcealedType");
        assert_eq!(
            TRANSIENT_MARKER_TYPES[2],
            "org.nspasteboard.AutoGeneratedType"
        );
    }

    #[test]
    fn osascript_keystroke_denial_maps_to_permission_error() {
        let error = map_osascript_error(
            b"execution error: System Events got an error: osascript is not allowed to send keystrokes. (1002)".to_vec(),
        );

        assert!(matches!(error, GetTextError::PermissionDenied { .. }));
    }

    #[test]
    fn pasteboard_snapshot_restores_multiple_items() {
        unsafe {
            let pool = NSAutoreleasePool::new(nil);
            let pasteboard = NSPasteboard::pasteboardWithUniqueName(nil);

            pasteboard.clearContents();
            let first = new_nspasteboard_item().unwrap();
            write_item_data(first, TEST_TYPE_ONE, b"one");
            let second = new_nspasteboard_item().unwrap();
            write_item_data(second, TEST_TYPE_TWO, b"two");

            let objects = NSArray::arrayWithObjects(nil, &[first, second]);
            assert_ne!(pasteboard.writeObjects(objects), NO);

            let snapshot = PasteboardSnapshot::capture(pasteboard);
            assert_eq!(snapshot.items.len(), 2);

            pasteboard.clearContents();
            snapshot.restore(pasteboard).unwrap();

            let restored_items = pasteboard.pasteboardItems();
            assert_ne!(restored_items, nil);
            assert_eq!(restored_items.count(), 2);

            let restored_first = restored_items.objectAtIndex(0);
            let restored_second = restored_items.objectAtIndex(1);
            assert_eq!(read_item_data(restored_first, TEST_TYPE_ONE), b"one");
            assert_eq!(read_item_data(restored_second, TEST_TYPE_TWO), b"two");

            pasteboard.releaseGlobally();
            pool.drain();
        }
    }

    unsafe fn write_item_data(item: id, type_name: &str, bytes: &[u8]) {
        let type_id = NSString::alloc(nil).init_str(type_name);
        let data = nsdata_from_bytes(bytes);
        assert_ne!(NSPasteboardItem::setData_forType(item, data, type_id), NO);
    }

    unsafe fn read_item_data(item: id, type_name: &str) -> Vec<u8> {
        let type_id = NSString::alloc(nil).init_str(type_name);
        let data = NSPasteboardItem::dataForType(item, type_id);
        nsdata_to_vec(data)
    }
}
